// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "../bridge";

export interface RefreshIn {
  refresh_token: string;
}

export interface TokenPair {
  access_token: string;
  /** Always bearer */
  token_type: string;
  /** Access token lifetime in seconds */
  expires_in: number;
  refresh_token: string;
  refresh_expires_in: number;
}

export interface LogoutIn {
  /** Also revoke every other session of this user */
  all_sessions?: boolean;
}

export interface LogoutOut {
  revoked_refresh_tokens: number;
}

/** The non-sensitive hospital settings every screen may show (the policy values are in admin settings). */
export interface HospitalSettingsOut {
  hospital_name: string;
  hospital_address: string;
  hospital_phone: string;
  hospital_timezone: string;
  currency_code: string;
  ticket_validity_hours: number;
  reception_max_discount_pct: number;
  opd_require_payment_before_queue: boolean;
  lab_require_payment_before_sample: boolean;
  password_min_length: number;
  maintenance_mode: boolean;
  /** A cash drop or a payable settlement at or above this needs a second, different person's credentials on the finance screens */
  large_cash_settlement_threshold: number;
  /** A one-person practice: the Owner who is the only possible approver may decide their own refund, waiver or credit (the approval's self_decision says when) */
  solo_practice_mode: boolean;
}

export interface WorkspaceInfoOut {
  code: string;
  label: string;
  label_ur: string;
  description: string;
  /** The titles of the workspace's screens, from the screen catalogue (GET /meta/handbook and the MCP server give each screen in full) */
  screens: string[];
  /** Screen ids of other workspaces its roles work in (the cashier: my_cash_shift, cash_back_prompts) */
  also_uses: string[];
  /** True for My Workspace (self_service): every user with an employee record has it, whatever their roles (GET /auth/workspaces lists it for them) */
  every_employee?: boolean;
  /** True for the PHC inspector's workspace: its logins are guests without an employee record, so they have no My Workspace */
  guest?: boolean;
}

export interface ErrorCodeOut {
  /** Switch on this, never on the message */
  code: string;
  http_status: number;
  /** The default text (an error may carry a more specific one) */
  message: string;
  retryable: boolean;
  category: string;
}

export interface EventInfoOut {
  event_type: string;
  description: string;
  /** Who receives it (permissions, the user or employee concerned) */
  audience: string;
  /** Payload field -> its type (e.g. "int|null") */
  payload_fields: Record<string, string>;
  priority: "normal" | "high" | "critical";
  /** The EXPECTED_HOSPITAL_WORKFLOWS.md sections it belongs to */
  workflow: string;
  /** How the backend prescribes showing it: interrupt (a full-screen alert until acknowledged), banner (on every window while it lasts), logout. null = not prescribed: `priority` is the delivery urgency, not a presentation rule */
  presentation: "interrupt" | "banner" | "logout" | null;
}

/** Rotate the refresh token and get a new access token — POST /api/v1/auth/refresh (who may call: public: no login (works before login)). */
export function refresh(body: RefreshIn): Promise<TokenPair> {
  return api<TokenPair>("POST", `/auth/refresh`, body);
}

/** End this session (or all sessions) — POST /api/v1/auth/logout (who may call: any logged-in user, for their own account (also before a forced password change where allowed)). */
export function logout(body: LogoutIn): Promise<LogoutOut> {
  return api<LogoutOut>("POST", `/auth/logout`, body);
}

/** All enumerated values, introspected from database CHECK constraints — GET /api/v1/meta/enums (who may call: any logged-in user). */
export function enums(): Promise<Record<string, string[]>> {
  return api<Record<string, string[]>>("GET", `/meta/enums`, undefined);
}

/** Non-sensitive hospital settings for UI display — GET /api/v1/meta/settings (who may call: any logged-in user). */
export function publicSettings(): Promise<HospitalSettingsOut> {
  return api<HospitalSettingsOut>("GET", `/meta/settings`, undefined);
}

/** UI workspaces and the screens each should contain — GET /api/v1/meta/workspaces (who may call: any logged-in user). */
export function workspacesMeta(): Promise<WorkspaceInfoOut[]> {
  return api<WorkspaceInfoOut[]>("GET", `/meta/workspaces`, undefined);
}

/** Every error code the API can return — GET /api/v1/meta/error-codes (who may call: public: no login (works before login)). */
export function errorCodes(): Promise<ErrorCodeOut[]> {
  return api<ErrorCodeOut[]>("GET", `/meta/error-codes`, undefined);
}

/** Realtime WebSocket event catalogue — GET /api/v1/meta/events (who may call: public: no login (works before login)). */
export function events(): Promise<EventInfoOut[]> {
  return api<EventInfoOut[]>("GET", `/meta/events`, undefined);
}
